import { forwardRef, type InputHTMLAttributes } from "react";

export const Slider = forwardRef<HTMLInputElement, Omit<InputHTMLAttributes<HTMLInputElement>, "type">>(({ className = "", style, ...props }, ref) => <input ref={ref} type="range" className={`co-h-2 co-w-full co-cursor-pointer co-appearance-none co-rounded-full co-bg-black/15 focus-visible:co-ring-2 disabled:co-opacity-50 ${className}`.trim()} style={{ accentColor: "black", ...style }} {...props} />);
Slider.displayName = "Slider";
